using System.IO;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor;
namespace LWS.TruckSports.Editor {
public static class SportsScenicGradeAuthoring {
 public static void Install(GameObject owner,Camera[] cameras,string folder,float exposure=-.4f){string directory="Assets/"+folder+"/Rendering";Directory.CreateDirectory(directory);string path=directory+"/Scenic grade.asset";var profile=AssetDatabase.LoadAssetAtPath<VolumeProfile>(path);if(profile==null){profile=ScriptableObject.CreateInstance<VolumeProfile>();profile.name=folder+" native URP scenic grade";var tone=profile.Add<Tonemapping>();tone.mode.Override(TonemappingMode.Neutral);var color=profile.Add<ColorAdjustments>();color.postExposure.Override(exposure);color.contrast.Override(4);color.saturation.Override(-3);var bloom=profile.Add<Bloom>();bloom.intensity.Override(.12f);bloom.threshold.Override(1);bloom.maxIterations.Override(4);bloom.downscale.Override(BloomDownscaleMode.Quarter);AssetDatabase.CreateAsset(profile,path);foreach(var c in profile.components)AssetDatabase.AddObjectToAsset(c,profile);EditorUtility.SetDirty(profile);}var found=owner.transform.Find("Native URP scenic grade");var volume=found!=null?found.GetComponent<Volume>():new GameObject("Native URP scenic grade").AddComponent<Volume>();volume.transform.SetParent(owner.transform,false);volume.isGlobal=true;volume.priority=9;volume.sharedProfile=profile;foreach(var camera in cameras){var data=camera.GetUniversalAdditionalCameraData();data.renderPostProcessing=true;data.volumeLayerMask|=1;camera.allowHDR=true;EditorUtility.SetDirty(camera);}AssetDatabase.SaveAssets();}
}
}
